INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (39,1,'👦🏠','大卫的妈妈总是说："大卫，不可以！"大卫站在椅子上够饼干罐。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (39,2,'👦🧱','大卫把客厅的墙画得满满的，妈妈气得直跺脚！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (39,3,'👦🦶','大卫穿着泥巴鞋在客厅跑来跑去，地板全脏了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (39,4,'👦🛁','大卫在浴缸里玩得水花四溅，把卫生间变成了游泳池！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (39,5,'👦🏃','大卫光着身子跑出门去，邻居们都惊呆了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (39,6,'🤗👦','虽然大卫总是捣蛋，但妈妈还是最爱他："大卫乖，我爱你！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (40,1,'🐊😰','鳄鱼牙疼得厉害，可他害怕去看牙医。牙医也害怕——他怕鳄鱼！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (40,2,'😬🐊','鳄鱼坐在候诊室发抖："我一定得去吗？"牙医在诊室里也发抖："我一定得看他吗？"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (40,3,'😰😬','鳄鱼看到牙医的钻头吓得张大嘴，牙医看到鳄鱼的大嘴也吓得发抖。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (40,4,'🦷💦','牙医小心地给鳄鱼补牙，鳄鱼疼得闭上眼睛。两人都想：\'再忍一下就好了。\'');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (40,5,'😅🤝','终于补好了！鳄鱼和牙医都松了一口气，互相说："多谢您了！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (40,6,'👋😬','鳄鱼和牙医都说："明年再见！"但心里都在想——我再也不想见到你啦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (41,1,'🦍🔑','动物园管理员晚安大猩猩！大猩猩偷偷拿走了管理员的钥匙。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (41,2,'🐘🚪','大猩猩打开了大象的门，大象跟着悄悄走出来。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (41,3,'🦁🚪','又打开了狮子的门、长颈鹿的门……所有动物都跟在管理员后面。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (41,4,'🏠🛏️','管理员回到家躺下睡觉，动物们一个一个也钻进了被窝。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (41,5,'😮👩','管理员太太说晚安，关灯——咦，怎么有好多双眼睛？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (41,6,'🦍🔑','管理员太太把动物们送回动物园，可大猩猩又偷偷跟着回来了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (42,1,'🦉🌙','夜深了，小青蛙说："我是不睡觉世界冠军！"小猪说："我才不是呢！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (42,2,'🐸📖','小青蛙躺在床上看书，眼睛瞪得大大的，一点都不困。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (42,3,'🐷🎵','小猪开始数绵羊，数到一百只还是精神得很。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (42,4,'🦊🧸','小狐狸抱着毛绒玩具说："我可以一整晚不睡！"可眼皮越来越重。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (42,5,'🐨💤','考拉打着大哈欠，小猪也快撑不住了，一个接一个倒下了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (42,6,'😴🏆','最后连小青蛙也撑不住啦！妈妈赢了，她才是不睡觉世界冠军！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (43,1,'🐻🍬','小熊哈利最喜欢吃甜食，就是不爱刷牙。"刷牙太麻烦啦！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (43,2,'🐻🦷','一天晚上哈利梦见自己的牙齿全掉了！没有牙齿怎么吃好吃的呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (43,3,'😱😭','哈利吓醒了，赶紧跑去照镜子——还好牙齿还在！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (43,4,'🐻🪥','从那以后，哈利每天早晚都认真刷牙，上刷刷下刷刷。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (43,5,'✨🦷','哈利去看牙医，牙医夸他："你的牙齿好白好亮啊！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (43,6,'😁🐻','哈利开心地露出大白牙，再也不偷懒不刷牙了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (44,1,'👦🏫','大卫上学啦！可是他在走廊里跑来跑去，老师说不可以。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (44,2,'👦✋','大卫上课的时候大声发言，还站起来手舞足蹈。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (44,3,'👦🍜','午餐时间大卫不排队，还跟同学抢食物，弄得满桌都是。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (44,4,'👦📚','大卫在图书馆大声说话，把其他小朋友都吓到了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (44,5,'👦🧹','大卫被罚擦桌子，他认真地擦呀擦，把教室打扫得干干净净。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (44,6,'⭐👦','老师表扬了大卫："做得好！"大卫学会了遵守学校的规则。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (45,1,'👦💥','大卫又惹麻烦了！他把花瓶打碎了，说："我不是故意的！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (45,2,'👦🍰','大卫偷吃蛋糕，却说："是狗狗吃的！"可是家里没有狗啊。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (45,3,'👦✋','作业没写完大卫说："是作业先动手的！"这算什么理由呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (45,4,'👦👖','大卫把裤子穿反了去上学，还说是新时尚。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (45,5,'👦🙅','每次犯错大卫都有借口，可是借口不能解决问题呀。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (45,6,'🤗👦','大卫终于说出了"对不起"，妈妈抱抱他。承认错误才是勇敢的孩子！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (46,1,'👶😬','小宝宝想拉粑粑了，可是小马桶在哪里呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (46,2,'🧸🚽','小熊娃娃也要拉粑粑，它坐在小马桶上——真棒！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (46,3,'🐶🚽','小狗也要拉粑粑，它也在小马桶上坐好了——真乖！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (46,4,'👶💪','小宝宝也勇敢地坐在小马桶上，嗯嗯——');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (46,5,'🎉👶','拉好啦！小宝宝自己擦屁屁，冲水——哗啦啦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (46,6,'👏✨','大家夸小宝宝真棒！用小马桶拉粑粑，一点都不难！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (47,1,'😊🦷','牙齿白白的真漂亮！可是小虫子最喜欢躲在牙齿里搞破坏。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (47,2,'🐛🍬','吃完甜食不刷牙，小虫子就在牙齿上挖洞洞，牙齿会疼哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (47,3,'🪥💧','挤上豌豆大小的牙膏，上刷刷下刷刷，里里外外都刷到。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (47,4,'⏰✨','每次刷牙要刷够两分钟，可以唱一首刷牙歌计时！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (47,5,'🦷🧵','刷完牙还要用牙线清理牙缝，不让小虫子有藏身的地方。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (47,6,'😁⭐','每天早晚认真刷牙，牙齿又白又亮，再也不怕牙虫啦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (48,1,'🛁🦆','洗澡时间到啦！小鸭子也来一起洗，扑通扑通跳进浴缸。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (48,2,'🧴💆','先洗头发，搓一搓好多泡泡，像戴了一顶白色帽子！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (48,3,'🧽🫧','用小毛巾擦擦手臂擦擦腿，身上好多泡泡滑溜溜。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (48,4,'👂👃','别忘洗洗小耳朵、小鼻子，还有脚趾缝也要洗干净。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (48,5,'💦🚿','冲水啦！温温的水冲掉泡泡，变得干干净净。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (48,6,'🧸🌟','洗完澡香喷喷，穿上睡衣真舒服，该睡觉啦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (49,1,'🌙🛏️','天黑了，该睡觉啦。小兔子换上睡衣，准备上床。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (49,2,'🪥💧','先刷刷牙，洗洗脸，把一天的灰尘都洗掉。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (49,3,'📚🧸','挑一本喜欢的绘本，抱着小熊听妈妈讲睡前故事。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (49,4,'🎵✨','妈妈轻轻唱摇篮曲，小兔子打了个哈欠。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (49,5,'⭐💤','盖上小被子，闭上眼睛，星星在窗外闪闪发光。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (49,6,'🌙😴','晚安，小兔子。晚安，全世界。做一个甜甜的梦吧。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (50,1,'🍽️👦','吃饭时间到！小猫已经乖乖坐好了，小男孩还在玩玩具。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (50,2,'🥦🥕','蔬菜有好多营养！西兰花像小树，胡萝卜让眼睛亮亮的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (50,3,'🥢🍚','端好碗拿好筷，一口一口慢慢吃，不说话不玩耍。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (50,4,'🙅📱','吃饭不看电视、不玩手机，专心吃饭才能好好消化。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (50,5,'😋💪','不挑食不偏食，肉肉蔬菜都要吃，才能长高高！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (50,6,'👏🍽️','吃完饭擦擦嘴，把碗筷放好。好好吃饭身体棒！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (51,1,'🧸🏠','玩完了积木和玩具，满地都是，房间乱糟糟的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (51,2,'📦🧸','积木回积木的家，小汽车回小汽车的家，每个玩具都有自己的家。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (51,3,'🧹💪','小熊说："我来帮忙！"把毛绒玩具放回箱子。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (51,4,'📚📚','绘本放回书架，画笔放回笔筒，一个也不能落下。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (51,5,'🗑️✨','废纸丢进垃圾桶，桌子擦干净，房间又变整齐啦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (51,6,'🎉😊','把玩具收起来，下次找起来更方便。养成收拾的好习惯！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (52,1,'😴🌊','小熊做了一个梦，梦里去了好多好玩的地方。可是早上起来——床湿了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (52,2,'🐻😰','小熊好害羞，偷偷把床单藏起来，不想让妈妈知道。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (52,3,'👩🤗','妈妈发现了，没有生气，温柔地说："没关系的，很多小朋友都会这样。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (52,4,'💧🌙','妈妈说："睡前少喝水，半夜想上厕所就叫妈妈。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (52,5,'⏰🚽','小熊设了小闹钟，半夜起来去上厕所，再也没尿床啦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (52,6,'🌞😊','尿床不可怕，慢慢就会好。爸爸妈妈永远爱你！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (53,1,'👶🩳','小宝宝长大了，要学着自己穿短裤啦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (53,2,'🔄🤔','先分清前面和后面，有标签的是后面，有图案的是前面。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (53,3,'🦵👖','一只脚伸进一个裤腿，嘿咻嘿咻往上拉。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (53,4,'💪👖','用力往上拉一拉，再把裤腰整一整。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (53,5,'❌😊','哎呀穿反了！没关系，脱下来重新穿，自己动手真棒！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (53,6,'🎉👕','穿好短裤再穿上衣，我会自己穿衣服啦！长大了一点点！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (54,1,'🐔🚶','母鸡萝丝去散步，她走过院子，一点也不知道后面跟着一只狐狸。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (54,2,'🐔🪓','狐狸扑向萝丝——踩到了钉耙，啪！打了自己的脸。萝丝继续走。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (54,3,'🐔🏊','萝丝走过池塘，狐狸又扑过来——扑通掉进了水里！萝丝继续走。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (54,4,'🐔🌾','萝丝经过干草堆，狐狸再扑——被干草埋住了！萝丝继续走。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (54,5,'🐔🏠','萝丝走过磨坊，狐狸紧跟——被面粉撒了一头白！萝丝继续走。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (54,6,'🐔🛏️','萝丝准时回家吃晚饭。狐狸呢？被蜜蜂追得抱头鼠窜！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (55,1,'🐷🌾','三只小猪长大了，各自去盖自己的房子。老大用稻草盖了一座草房。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (55,2,'🐷🪵','老二用木头盖了一座木房，老三用砖头盖了一座砖房，最结实！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (55,3,'🐺💨','大灰狼来了！他对草房吹了口气——呼！草房飞走了！老大跑到老二家。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (55,4,'🐺💨','大灰狼对木房吹了口气——呼！木房也倒了！两只小猪跑到老三家。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (55,5,'🐺💨','大灰狼对砖房使劲吹——呼呼呼！砖房一动不动！大灰狼怎么也吹不倒。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (55,6,'🐺🔥','大灰狼从烟囱爬进去，掉进了滚烫的热水里！三只小猪从此再也不怕大灰狼了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (56,1,'👧🧺','小红帽提着篮子去森林里看望生病的外婆，妈妈叮嘱她不要离开大路。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (56,2,'👧🐺','大灰狼拦住了小红帽："你去哪儿呀？"小红帽说去看外婆，还告诉了外婆家的路。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (56,3,'🐺🏃','大灰狼抄近路跑到外婆家，一口吞下了外婆，然后穿上外婆的衣服躺在床上。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (56,4,'👧👀','小红帽到了外婆家："外婆，你的眼睛好大！耳朵好大！牙齿好大！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (56,5,'🐺👄','"牙齿大是为了吃掉你！"大灰狼扑向小红帽——');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (56,6,'🪓✨','猎人路过听见声音，救出了小红帽和外婆。小红帽再也不跟陌生人说话了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (57,1,'🐢🤔','动物们看着天上的月亮，好奇极了："月亮是什么味道呢？是甜的还是咸的？"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (57,2,'🐘🐢','大象站在乌龟背上，伸长了鼻子——够不着！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (57,3,'🦒🐘','长颈鹿站在大象背上，伸长了脖子——还是够不着！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (57,4,'🦓🦒','斑马站在长颈鹿背上，够不着。狮子又爬上来，还是够不着！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (57,5,'🐭🦓','小老鼠爬到最上面，它一伸手——月亮被咬了一小口！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (57,6,'😋🌙','月亮的味道真甜啊！动物们每人分了一小片，这是他们吃过最好吃的东西！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (58,1,'🏠😴','有一座打瞌睡的房子，房子里每个人都在睡觉。老奶奶在床上打瞌睡。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (58,2,'👦😴','小男孩睡在老奶奶身上，狗睡在小男孩身上，猫睡在狗身上。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (58,3,'🐭😴','老鼠睡在猫身上，一切都安安静静，大家都打着瞌睡。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (58,4,'🛏️💤','房子里好静好静，天上一滴雨都没有，空气沉甸甸的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (58,5,'🐛⚡','突然，一只不睡觉的跳蚤咬了老鼠一口！老鼠吓醒了猫，猫吓醒了狗……');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (58,6,'🌞🎉','大家都醒了！太阳也出来了，打瞌睡的房子变成了欢乐的房子！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (59,1,'🐭🍪','要是你给老鼠吃饼干，他就会要一杯牛奶。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (59,2,'🥛🪥','给了牛奶，他就要照镜子看看有没有牛奶胡子，然后要一把小剪刀修修胡子。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (59,3,'🧹🧽','修完胡子他发现要打扫，打扫完了又要去洗澡，洗完澡又要一条毛巾。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (59,4,'📦🛏️','擦完毛巾他又想找个小箱子当床睡觉，睡前还要听一个故事。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (59,5,'📚✏️','听完故事他又要画画，画完画又要贴在冰箱上，然后又发现冰箱里有……');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (59,6,'🍪😊','冰箱里有饼干！要是你给他吃饼干，他又会要一杯牛奶。一切又重新开始啦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (60,1,'🐰👗','小兔子有一条雪白的连衣裙，走在花园里裙子就变成花朵图案。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (60,2,'🌸👗','走进花田，连衣裙变成了花朵的图案，好漂亮啊！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (60,3,'🌧️👗','下雨了，连衣裙变成了雨点图案，一滴一滴的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (60,4,'🌾👗','走过草籽田，连衣裙变成了草籽图案，一粒一粒的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (60,5,'🐦👗','小鸟飞来了，连衣裙变成了小鸟的图案，一只一只的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (60,6,'✨👗','傍晚到了，连衣裙变成了晚霞的图案。明天穿它又会变成什么呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (61,1,'🐭🌲','小老鼠在森林里散步，遇到了狐狸。狐狸说："我要吃掉你！"小老鼠说："不行，我要见咕噜牛。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (61,2,'🐍🌲','又遇到蛇和猫头鹰，小老鼠都说："咕噜牛最喜欢吃你们！"他们都吓跑了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (61,3,'😱🐮','小老鼠正得意，突然真的碰到了咕噜牛！咕噜牛说："我最爱吃老鼠！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (61,4,'🐭🧠','小老鼠急中生智："我是森林里最可怕的！你不信就跟我走。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (61,5,'🐮👀','狐狸、蛇、猫头鹰看到咕噜牛跟着小老鼠走过来——吓得拼命跑！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (61,6,'🐭🎉','咕噜牛以为他们都怕小老鼠，也吓得跑掉了！小老鼠悠然自得地吃起了坚果。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (62,1,'🧸🌲','咕噜牛爸爸说："千万别去那片森林，那里有只大坏鼠！"小咕噜牛偏要去看看。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (62,2,'🧸🐍','雪地上有蛇的痕迹，小咕噜牛问："你是不是大坏鼠？"蛇说不是，游走了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (62,3,'🧸🦉','树上有猫头鹰的影子，小咕噜牛问："你是大坏鼠吗？"猫头鹰飞走了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (62,4,'🧸🦊','狐狸说大坏鼠在树底下，小咕噜牛越来越害怕了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (62,5,'🧸🐭','小咕噜牛真的遇到了小老鼠！小老鼠吹了声口哨，咕噜牛爸爸出现了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (62,6,'🧸🏃','大咕噜牛喊："快跑！大坏鼠来了！"小咕噜牛吓坏了，跟着爸爸拼命跑回了家。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (63,1,'👨🛍️','乔治是城里最邋遢的巨人，他决定去买新衣服，变成最漂亮的巨人！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (63,2,'👨👔','乔治买了衬衫、裤子、皮带、领带、袜子和皮鞋，真精神！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (63,3,'🦒👔','长颈鹿的脖子冷，乔治把领带给它当围巾。山羊的帆船缺帆，他把衬衫给了它。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (63,4,'🐭🧦','小老鼠的房子烧了，乔治把皮鞋给它当房子。狐狸的睡袋坏了，他把袜子给了它。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (63,5,'🐕🩲','小狗需要过沼泽，乔治把皮带当小桥。可他的裤子掉下来了——原来没皮带了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (63,6,'😊🏅','乔治穿着旧衣服回到商店，动物们送给他一顶金冠和一封信："你是心眼最好的巨人！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (64,1,'👵🏠','小老太太嫌房子太小了，请聪明老先生帮忙。老先生说："把母鸡抱进屋。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (64,2,'🐔🏠','母鸡在屋里扑腾，老太太说："更挤了！"老先生说："把山羊也牵进来。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (64,3,'🐐🏠','山羊在屋里乱撞，老太太说："太挤了！"老先生说："再把猪也赶进来。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (64,4,'🐷🏠','猪在屋里乱拱，老太太说："受不了了！"老先生说："把奶牛也牵进来。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (64,5,'🐄🏠','屋里乱成一锅粥！老先生终于说："现在把它们全放出去吧。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (64,6,'🏠😊','老太太觉得房子一下子好大好宽敞！原来房子没变，心变了就不一样了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (65,1,'🧹🧙‍♀️','女巫有一把扫帚，她骑着扫帚在天上飞。风把她的帽子吹走了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (65,2,'🐕🧹','小狗帮她捡回帽子，请求坐上扫帚，女巫同意了。扫帚上多了小狗。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (65,3,'🐦🧹','小鸟帮她捡回蝴蝶结，也坐上了扫帚。扫帚上越来越多动物了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (65,4,'🐸🧹','青蛙帮她找回魔杖，扫帚上更挤了——咔嚓！扫帚断了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (65,5,'🐉🔥','一条喷火龙要把女巫吃掉！小动物们从树丛里冲出来："怪物来啦！"吓跑了龙。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (65,6,'✨🧹','女巫用魔杖变出了一把超级豪华扫帚，每个动物都有自己的座位！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (66,1,'👨‍👩‍👦‍👦🐻','我们要去捉狗熊！我们要捉一只大大的！过一个草地——沙沙沙！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (66,2,'🌊🏃','过一条河——哗啦啦！水好凉，但我们必须过去。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (66,3,'💩🚶','过一片泥地——吧唧吧唧！泥好深，但我们继续走。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (66,4,'🌲🧗','过一片树林——磕磕碰碰！树好密，但我们要捉狗熊！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (66,5,'❄️🥶','过一场暴风雪——呜呜呜！风好大，但我们不怕！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (66,6,'🐻🏃','终于到了山洞——一个亮晶晶的鼻子！是狗熊！快跑快跑快跑——跑回了家！再也不去捉狗熊了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (67,1,'👴🚣','甘伯伯有一条船。小朋友说："带我一起去好吗？"甘伯伯说："好，但别乱蹦。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (67,2,'🐷🚣','猪说："我也去好吗？"甘伯伯说："好，但别乱晃。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (67,3,'🐑🚣','羊、鸡、牛……大家一个一个上了船，甘伯伯都说好，但都叮嘱别闹。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (67,4,'🌊😱','船在河上漂，动物们越来越兴奋，蹦啊晃啊叫啊——船翻了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (67,5,'💦🏊','大家都掉进了河里！甘伯伯说："我早就说了别闹嘛。"大家爬上岸晒太阳。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (67,6,'🍵😊','甘伯伯请大家喝茶吃点心。下次还一起去游河吗？当然！但别再闹啦。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (68,1,'👴🚗','甘伯伯有一辆汽车，大家说："带我们去兜风吧！"甘伯伯说："好呀。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (68,2,'🐷🚗','猪上了车，羊上了车，鸡也上了车，车子越来越挤了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (68,3,'☁️🚗','太阳不见了，乌云来了，风也越来越大。甘伯伯说："要下雨了，快上车！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (68,4,'🌧️🚗','大雨哗啦啦地下，路变成了泥巴路，车轮子越陷越深。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (68,5,'😱🚗','车子陷进泥里出不来了！大家下来一起推——一、二、三！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (68,6,'🌞🎉','终于推出来了！雨也停了，太阳出来了。兜风真开心，下次还去！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (69,1,'👦🎒','约翰派克罗门麦肯席上学又迟到了。老师说："你为什么迟到？"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (69,2,'🐊👖','"路上有只鳄鱼从下水道钻出来咬我的书包！"老师说："下水道里哪来的鳄鱼？罚你写三百遍！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (69,3,'🦁👖','第二天又迟到了。"有只狮子从树丛里钻出来咬破了我的裤子！"老师不信，又罚他。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (69,4,'🌊💦','第三天又迟到。"路上遇到了巨浪！"老师气坏了，罚他关禁闭。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (69,5,'👴🦍','第四天，老师迟到了！一只大猩猩抓住了他！约翰说："这里哪来的猩猩？"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (69,6,'😏✨','老师终于知道被人冤枉的滋味了。有时候，真相比你想的更离奇！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (70,1,'🐊🚶','哥尼流是一只与众不同的鳄鱼，他可以用两条腿直立行走！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (70,2,'🐊😒','其他鳄鱼说："那有什么用？"哥尼流很伤心，决定离开。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (70,3,'🐊🐒','在路上，哥尼流遇到了猴子，学会了用尾巴倒挂在树上。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (70,4,'🐊🏠','哥尼流回到河岸，给大家表演倒挂。鳄鱼们又说："那有什么用？"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (70,5,'🐊👀','可是哥尼流回头看时，发现鳄鱼们都在偷偷练习用两条腿走路！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (70,6,'🐊✨','改变不需要所有人的认可。当你勇敢做自己，世界也在悄悄改变。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (71,1,'🐭🌾','田鼠们都在忙着收集玉米、坚果和稻草准备过冬。只有阿佛坐在一旁。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (71,2,'🐭☀️','"你在做什么？"阿佛说："我在收集阳光，冬天太冷了。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (71,3,'🐭🎨','"你在做什么？"阿佛说："我在收集颜色，冬天是灰色的。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (71,4,'🐭📝','"你在做什么？"阿佛说："我在收集词语，冬天太长了。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (71,5,'❄️🐭','冬天来了，食物吃完了，大家又冷又无聊。阿佛站了起来——');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (71,6,'☀️✨','阿佛念出了一首美丽的诗，大家仿佛看见了阳光和色彩。诗也能温暖冬天！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (72,1,'🐭😢','亚历山大是一只真老鼠，每天要找吃的还要躲猫。威利是发条老鼠，小主人可喜欢它了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (72,2,'🐭🌟','亚历山大好羡慕威利："如果我也是发条老鼠就好了，有人爱有人抱。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (72,3,'🦎✨','蜥蜴告诉亚历山大："找到紫色鹅卵石，就能让魔法蜥蜴实现愿望。"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (72,4,'🐭🔍','亚历山大在花园里找啊找，终于在月夜下找到了一颗紫色鹅卵石！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (72,5,'🐭🤔','亚历山大正要许愿，却发现威利被扔进了旧玩具箱——没人要了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (72,6,'🐭🎉','亚历山大许愿让威利变成真老鼠！蜥蜴施了魔法，两只小老鼠一起快乐地跳舞。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (73,1,'🐭🎨','玛修和爸爸妈妈住在阁楼上。爸爸妈妈希望他做医生，可玛修喜欢画画。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (73,2,'🐭🏛️','一天玛修去了美术馆，他看到了好多美丽的画，心砰砰跳！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (73,3,'🐭💭','玛修闭上眼睛，梦见自己走进了一幅幅画里，颜色和线条在身边飞舞。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (73,4,'🐭🖌️','玛修拿起画笔，画出了梦里看到的世界——有阳光、有大海、有星星。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (73,5,'🐭🖼️','玛修的画让所有人都惊叹："这是真正的画家画的！"');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (73,6,'🐭✨','玛修成了大画家。只要勇敢追寻梦想，你的画笔就能画出整个世界！');